#include <algorithm>
#include <fstream>
#include <iostream>
#include <memory>
#include <string>
#include <vector>
using namespace std;

class Item {
public:
    Item(int id, const string& name) : id(id), name(name) {}
    int id;
    string name;
    bool out = false;
};

int main() {
    vector<unique_ptr<Item>> shelf;
    shelf.push_back(make_unique<Item>(1, "鱼干小百科"));
    shelf.push_back(make_unique<Item>(2, "猫粮月报"));
    shelf.push_back(make_unique<Item>(3, "大肥鱼自传"));

    for (int i = 0; i < {n}; i++) {
        int id = 0;
        cin >> id;
        bool ok = false;
        for (auto& it : shelf) {
            if (it->id != id) continue;
            if (!it->out) { it->out = true; ok = true; }
            break;
        }
        cout << (ok ? "办好了" : "办不了") << " " << id << endl;
    }

    ofstream outFile("books.txt");
    for (const auto& it : shelf) outFile << it->id << " " << it->name << " " << it->out << endl;
    outFile.close();
    cout << "存好了" << endl;

    shelf.clear();
    ifstream inFile("books.txt");
    int id = 0;
    bool out = false;
    string name;
    while (inFile >> id >> name >> out) {
        auto it = make_unique<Item>(id, name);
        it->out = out;
        shelf.push_back(move(it));
    }
    cout << "读回来了" << endl;

    for (const auto& it : shelf) cout << it->id << " " << it->name << (it->out ? " 借出" : " 在架") << endl;

    int total = count_if(shelf.begin(), shelf.end(), [](const unique_ptr<Item>& p) { return p->out; });
    cout << "借出去 " << total << " 件" << endl;
    return 0;
}
